-- Phase 4 additive EPUB publishing guideline domain. Not applied to a live database.
-- Reuses existing users, app_files/blobs, project revisions/events, QA and background jobs.

CREATE TABLE IF NOT EXISTS publishing_guideline_profiles (tenant_id BIGINT UNSIGNED NOT NULL,id CHAR(36) NOT NULL,service VARCHAR(32) NOT NULL DEFAULT 'epub',scope VARCHAR(16) NOT NULL,project_id CHAR(36) NULL,client_name VARCHAR(100) NOT NULL,owner_id BIGINT UNSIGNED NOT NULL,shared_staff TINYINT(1) NOT NULL DEFAULT 0,current_version INT UNSIGNED NOT NULL,archived TINYINT(1) NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),KEY guideline_catalogue(tenant_id,service,scope,archived,client_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS publishing_guideline_versions (tenant_id BIGINT UNSIGNED NOT NULL,profile_id CHAR(36) NOT NULL,version INT UNSIGNED NOT NULL,payload_json JSON NOT NULL,source_proof_json JSON NULL,status VARCHAR(24) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL,approved_at DATETIME NULL,effective_at DATETIME NULL,review_note VARCHAR(1000) NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,profile_id,version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_guideline_documents (tenant_id BIGINT UNSIGNED NOT NULL,id CHAR(36) NOT NULL,project_id CHAR(36) NOT NULL,file_id BIGINT UNSIGNED NOT NULL,filename VARCHAR(255) NOT NULL,format VARCHAR(12) NOT NULL,sha256 CHAR(64) NOT NULL,size_bytes INT UNSIGNED NOT NULL,uploaded_by BIGINT UNSIGNED NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'uploaded',latest_job_id BIGINT UNSIGNED NULL,active_extraction_id CHAR(36) NULL,request_count INT UNSIGNED NOT NULL DEFAULT 0,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),KEY guideline_project_documents(tenant_id,project_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_guideline_extractions (tenant_id BIGINT UNSIGNED NOT NULL,id CHAR(36) NOT NULL,document_id CHAR(36) NOT NULL,job_id BIGINT UNSIGNED NOT NULL,job_attempt INT UNSIGNED NOT NULL,run_order BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,UNIQUE KEY guideline_extraction_order(run_order),source_sha256 CHAR(64) NOT NULL,mode VARCHAR(12) NOT NULL,language_mode VARCHAR(16) NOT NULL,result_json JSON NOT NULL,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),UNIQUE KEY guideline_extraction_attempt(tenant_id,document_id,job_id,job_attempt),KEY guideline_extraction_history(tenant_id,document_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_guideline_assessments (tenant_id BIGINT UNSIGNED NOT NULL,id CHAR(36) NOT NULL,project_id CHAR(36) NOT NULL,project_revision INT UNSIGNED NOT NULL,snapshot_sha256 CHAR(64) NOT NULL,record_order BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,UNIQUE KEY guideline_assessment_order(record_order),rule_id VARCHAR(160) NOT NULL,output_id CHAR(36) NOT NULL,output_sha256 CHAR(64) NOT NULL,result_json JSON NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),KEY guideline_assessment_history(tenant_id,project_id,project_revision,rule_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS conversion_guideline_exceptions (tenant_id BIGINT UNSIGNED NOT NULL,id CHAR(36) NOT NULL,project_id CHAR(36) NOT NULL,project_revision INT UNSIGNED NOT NULL,rule_id VARCHAR(160) NOT NULL,record_order BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,UNIQUE KEY guideline_exception_order(record_order),snapshot_sha256 CHAR(64) NOT NULL,status VARCHAR(24) NOT NULL,detail_json JSON NOT NULL,actor_id BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(tenant_id,id),KEY guideline_exception_history(tenant_id,project_id,project_revision,rule_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
